import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

export async function GET(request: Request) {
    try {
        // #region agent log
        fetch('http://127.0.0.1:7937/ingest/db7347b1-8844-4ae1-a267-d775b365e441',{method:'POST',headers:{'Content-Type':'application/json','X-Debug-Session-Id':'b562ca'},body:JSON.stringify({sessionId:'b562ca',runId:'pre-debug',hypothesisId:'H1_api_file_exists_check',location:'src/app/api/data/route.ts:GET:start',message:'/api/data GET start',data:{url:request.url,category:(new URL(request.url).searchParams.get('category')||'it'),cwd:process.cwd()},timestamp:Date.now()})}).catch(()=>{});
        // #endregion
        const { searchParams } = new URL(request.url);
        const category = searchParams.get('category') || 'it'; // 기본값 'it'
        
        const fileName = `${category}.json`;
        const filePath = path.join(process.cwd(), 'data', fileName);

        // #region agent log
        fetch('http://127.0.0.1:7937/ingest/db7347b1-8844-4ae1-a267-d775b365e441',{method:'POST',headers:{'Content-Type':'application/json','X-Debug-Session-Id':'b562ca'},body:JSON.stringify({sessionId:'b562ca',runId:'pre-debug',hypothesisId:'H1_api_file_exists_check',location:'src/app/api/data/route.ts:GET:filePath',message:'checking data file',data:{category,fileName,filePath,fileExists:fs.existsSync(filePath)},timestamp:Date.now()})}).catch(()=>{});
        // #endregion
        
        if (!fs.existsSync(filePath)) {
            // 파일이 없는 경우 빈 데이터 반환
            return NextResponse.json({ 
                success: true, 
                data: { category, dateStr: '없음', articles: [] } 
            });
        }

        const content = fs.readFileSync(filePath, 'utf-8');
        const fileData = JSON.parse(content);

        // #region agent log
        fetch('http://127.0.0.1:7937/ingest/db7347b1-8844-4ae1-a267-d775b365e441',{method:'POST',headers:{'Content-Type':'application/json','X-Debug-Session-Id':'b562ca'},body:JSON.stringify({sessionId:'b562ca',runId:'pre-debug',hypothesisId:'H1_api_file_exists_check',location:'src/app/api/data/route.ts:GET:afterParse',message:'parsed data file',data:{filePath,articlesLen:fileData?.articles?.length,firstSummaryType:typeof fileData?.articles?.[0]?.summary,dateStr:fileData?.dateStr},timestamp:Date.now()})}).catch(()=>{});
        // #endregion

        return NextResponse.json({ success: true, data: fileData });
    } catch (error) {
        // #region agent log
        fetch('http://127.0.0.1:7937/ingest/db7347b1-8844-4ae1-a267-d775b365e441',{method:'POST',headers:{'Content-Type':'application/json','X-Debug-Session-Id':'b562ca'},body:JSON.stringify({sessionId:'b562ca',runId:'pre-debug',hypothesisId:'H1_api_file_exists_check',location:'src/app/api/data/route.ts:GET:catch',message:'error while reading/parsing',data:{errorMessage:error instanceof Error?error.message:String(error)},timestamp:Date.now()})}).catch(()=>{});
        // #endregion
        return NextResponse.json({ success: false });
    }
}
